    { const char * tb_v962 = "#endif\n"; *(const char * *)tb_grow(v_lines) = tb_v962; }
    { const char * tb_v963 = "// ---------- temp: временная память ----------\n"; *(const char * *)tb_grow(v_lines) = tb_v963; }
    { const char * tb_v964 = "// Внутри блока temp память берётся из больших кусков подряд (быстро, без malloc),\n"; *(const char * *)tb_grow(v_lines) = tb_v964; }
    { const char * tb_v965 = "// а в конце блока все куски отдаются разом. У каждого ядра свои куски.\n"; *(const char * *)tb_grow(v_lines) = tb_v965; }
    { const char * tb_v966 = "typedef struct { char *mem; long long size, used; } tb_chunk;\n"; *(const char * *)tb_grow(v_lines) = tb_v966; }
    { const char * tb_v967 = "typedef struct { int n; long long used; } tb_mark;\n"; *(const char * *)tb_grow(v_lines) = tb_v967; }
    { const char * tb_v968 = "static _Thread_local tb_chunk *tb_chunks = 0;\n"; *(const char * *)tb_grow(v_lines) = tb_v968; }
    { const char * tb_v969 = "static _Thread_local int tb_nchunks = 0, tb_capchunks = 0, tb_temp_depth = 0;\n"; *(const char * *)tb_grow(v_lines) = tb_v969; }
    { const char * tb_v970 = "static int tb_in_temp(const void *p) {\n"; *(const char * *)tb_grow(v_lines) = tb_v970; }
    { const char * tb_v971 = "    for (int i = tb_nchunks - 1; i >= 0; i--) {\n"; *(const char * *)tb_grow(v_lines) = tb_v971; }
    { const char * tb_v972 = "        if ((const char *)p >= tb_chunks[i].mem && (const char *)p < tb_chunks[i].mem + tb_chunks[i].size) return 1;\n"; *(const char * *)tb_grow(v_lines) = tb_v972; }
    { const char * tb_v973 = "    }\n"; *(const char * *)tb_grow(v_lines) = tb_v973; }
    { const char * tb_v974 = "    return 0;\n"; *(const char * *)tb_grow(v_lines) = tb_v974; }
    { const char * tb_v975 = "}\n"; *(const char * *)tb_grow(v_lines) = tb_v975; }
    { const char * tb_v976 = "static void *tb_temp_alloc(long long n) {\n"; *(const char * *)tb_grow(v_lines) = tb_v976; }
    { const char * tb_v977 = "    n = n > 0 ? (n + 15) & ~15LL : 16;\n"; *(const char * *)tb_grow(v_lines) = tb_v977; }
    { const char * tb_v978 = "    tb_chunk *c = tb_nchunks > 0 ? &tb_chunks[tb_nchunks - 1] : 0;\n"; *(const char * *)tb_grow(v_lines) = tb_v978; }
    { const char * tb_v979 = "    if (c == 0 || c->used + n > c->size) {\n"; *(const char * *)tb_grow(v_lines) = tb_v979; }
    { const char * tb_v980 = "        long long size = c != 0 ? c->size * 2 : (1LL << 20);\n"; *(const char * *)tb_grow(v_lines) = tb_v980; }
    { const char * tb_v981 = "        if (size < n) size = n;\n"; *(const char * *)tb_grow(v_lines) = tb_v981; }
    { const char * tb_v982 = "        if (tb_nchunks == tb_capchunks) {\n"; *(const char * *)tb_grow(v_lines) = tb_v982; }
    { const char * tb_v983 = "            tb_capchunks = tb_capchunks * 2 + 8;\n"; *(const char * *)tb_grow(v_lines) = tb_v983; }
    { const char * tb_v984 = "            tb_chunks = realloc(tb_chunks, sizeof(tb_chunk) * tb_capchunks);\n"; *(const char * *)tb_grow(v_lines) = tb_v984; }
    { const char * tb_v985 = "            if (tb_chunks == 0) tb_crash(0, \"не хватило памяти\");\n"; *(const char * *)tb_grow(v_lines) = tb_v985; }
    { const char * tb_v986 = "        }\n"; *(const char * *)tb_grow(v_lines) = tb_v986; }
    { const char * tb_v987 = "        char *mem = malloc(size);\n"; *(const char * *)tb_grow(v_lines) = tb_v987; }
    { const char * tb_v988 = "        if (mem == 0) tb_crash(0, \"не хватило памяти\");\n"; *(const char * *)tb_grow(v_lines) = tb_v988; }
    { const char * tb_v989 = "        tb_chunks[tb_nchunks] = (tb_chunk){mem, size, 0};\n"; *(const char * *)tb_grow(v_lines) = tb_v989; }
    { const char * tb_v990 = "        c = &tb_chunks[tb_nchunks];\n"; *(const char * *)tb_grow(v_lines) = tb_v990; }
    { const char * tb_v991 = "        tb_nchunks += 1;\n"; *(const char * *)tb_grow(v_lines) = tb_v991; }
    { const char * tb_v992 = "    }\n"; *(const char * *)tb_grow(v_lines) = tb_v992; }
    { const char * tb_v993 = "    void *p = c->mem + c->used;\n"; *(const char * *)tb_grow(v_lines) = tb_v993; }
    { const char * tb_v994 = "    c->used += n;\n"; *(const char * *)tb_grow(v_lines) = tb_v994; }
    { const char * tb_v995 = "    return p;\n"; *(const char * *)tb_grow(v_lines) = tb_v995; }
    { const char * tb_v996 = "}\n"; *(const char * *)tb_grow(v_lines) = tb_v996; }
    { const char * tb_v997 = "// метки открытых temp (и арен шага / функции): самая последняя — текущая область\n"; *(const char * *)tb_grow(v_lines) = tb_v997; }
    { const char * tb_v998 = "static _Thread_local tb_mark *tb_marks = 0;\n"; *(const char * *)tb_grow(v_lines) = tb_v998; }
    { const char * tb_v999 = "static _Thread_local int tb_capmarks = 0;\n"; *(const char * *)tb_grow(v_lines) = tb_v999; }
    { const char * tb_v1000 = "static inline tb_mark tb_temp_begin(void) {\n"; *(const char * *)tb_grow(v_lines) = tb_v1000; }
    { const char * tb_v1001 = "    tb_mark m = {tb_nchunks, tb_nchunks > 0 ? tb_chunks[tb_nchunks - 1].used : 0};\n"; *(const char * *)tb_grow(v_lines) = tb_v1001; }
    { const char * tb_v1002 = "    if (tb_temp_depth == tb_capmarks) {\n"; *(const char * *)tb_grow(v_lines) = tb_v1002; }
    { const char * tb_v1003 = "        tb_capmarks = tb_capmarks * 2 + 16;\n"; *(const char * *)tb_grow(v_lines) = tb_v1003; }
