    { const char * tb_v1575 = "    }\n"; *(const char * *)tb_grow(v_lines) = tb_v1575; }
    { const char * tb_v1576 = "    if (d->mode == 2) {\n"; *(const char * *)tb_grow(v_lines) = tb_v1576; }
