    { const char * tb_v1737 = "}\n"; *(const char * *)tb_grow(v_lines) = tb_v1737; }
    { const char * tb_v1738 = "// ---------- холодные качества obj: своя память, подряд, отдельно от горячих ----------\n"; *(const char * *)tb_grow(v_lines) = tb_v1738; }
    { const char * tb_v1739 = "static void *tb_cold_mem(long long n) {\n"; *(const char * *)tb_grow(v_lines) = tb_v1739; }
    { const char * tb_v1740 = "    if (tb_temp_depth > 0) return tb_mem(n);\n"; *(const char * *)tb_grow(v_lines) = tb_v1740; }
    { const char * tb_v1741 = "    static _Thread_local char *p = 0;\n"; *(const char * *)tb_grow(v_lines) = tb_v1741; }
    { const char * tb_v1742 = "    static _Thread_local long long left = 0;\n"; *(const char * *)tb_grow(v_lines) = tb_v1742; }
    { const char * tb_v1743 = "    n = (n + 15) & ~15LL;\n"; *(const char * *)tb_grow(v_lines) = tb_v1743; }
    { const char * tb_v1744 = "    if (left < n) {\n"; *(const char * *)tb_grow(v_lines) = tb_v1744; }
    { const char * tb_v1745 = "        long long size = n > 65536 ? n : 65536;\n"; *(const char * *)tb_grow(v_lines) = tb_v1745; }
    { const char * tb_v1746 = "        p = malloc(size);\n"; *(const char * *)tb_grow(v_lines) = tb_v1746; }
    { const char * tb_v1747 = "        if (!p) tb_crash(0, \"не хватило памяти\");\n"; *(const char * *)tb_grow(v_lines) = tb_v1747; }
    { const char * tb_v1748 = "        left = size;\n"; *(const char * *)tb_grow(v_lines) = tb_v1748; }
    { const char * tb_v1749 = "    }\n"; *(const char * *)tb_grow(v_lines) = tb_v1749; }
    { const char * tb_v1750 = "    void *r = p;\n"; *(const char * *)tb_grow(v_lines) = tb_v1750; }
    { const char * tb_v1751 = "    p += n;\n"; *(const char * *)tb_grow(v_lines) = tb_v1751; }
    { const char * tb_v1752 = "    left -= n;\n"; *(const char * *)tb_grow(v_lines) = tb_v1752; }
    { const char * tb_v1753 = "    memset(r, 0, n);\n"; *(const char * *)tb_grow(v_lines) = tb_v1753; }
    { const char * tb_v1754 = "    return r;\n"; *(const char * *)tb_grow(v_lines) = tb_v1754; }
    { const char * tb_v1755 = "}\n"; *(const char * *)tb_grow(v_lines) = tb_v1755; }
    { const char * tb_v1756 = "// ---------- obj: память пачкой ----------\n"; *(const char * *)tb_grow(v_lines) = tb_v1756; }
    { const char * tb_v1757 = "// obj никогда не отдают по одному (нет free), поэтому их не надо брать через malloc\n"; *(const char * *)tb_grow(v_lines) = tb_v1757; }
    { const char * tb_v1758 = "// поштучно: берём кусок на тысячи объектов и раздаём подряд. Быстрее, и соседние\n"; *(const char * *)tb_grow(v_lines) = tb_v1758; }
    { const char * tb_v1759 = "// объекты лежат рядом в памяти. Внутри temp и шага цикла — как раньше, из временной памяти.\n"; *(const char * *)tb_grow(v_lines) = tb_v1759; }
    { const char * tb_v1760 = "static void *tb_obj_mem(long long n) {\n"; *(const char * *)tb_grow(v_lines) = tb_v1760; }
    { const char * tb_v1761 = "    if (tb_temp_depth > 0) return tb_mem(n);\n"; *(const char * *)tb_grow(v_lines) = tb_v1761; }
    { const char * tb_v1762 = "    static _Thread_local char *p = 0;\n"; *(const char * *)tb_grow(v_lines) = tb_v1762; }
    { const char * tb_v1763 = "    static _Thread_local long long left = 0;\n"; *(const char * *)tb_grow(v_lines) = tb_v1763; }
    { const char * tb_v1764 = "    n = (n + 7) & ~7LL;\n"; *(const char * *)tb_grow(v_lines) = tb_v1764; }
    { const char * tb_v1765 = "    if (left < n) {\n"; *(const char * *)tb_grow(v_lines) = tb_v1765; }
    { const char * tb_v1766 = "        long long size = n > (1LL << 20) ? n : (1LL << 20);\n"; *(const char * *)tb_grow(v_lines) = tb_v1766; }
    { const char * tb_v1767 = "        p = malloc(size);\n"; *(const char * *)tb_grow(v_lines) = tb_v1767; }
    { const char * tb_v1768 = "        if (!p) tb_crash(0, \"не хватило памяти\");\n"; *(const char * *)tb_grow(v_lines) = tb_v1768; }
    { const char * tb_v1769 = "        left = size;\n"; *(const char * *)tb_grow(v_lines) = tb_v1769; }
    { const char * tb_v1770 = "    }\n"; *(const char * *)tb_grow(v_lines) = tb_v1770; }
    { const char * tb_v1771 = "    void *r = p;\n"; *(const char * *)tb_grow(v_lines) = tb_v1771; }
    { const char * tb_v1772 = "    p += n;\n"; *(const char * *)tb_grow(v_lines) = tb_v1772; }
    { const char * tb_v1773 = "    left -= n;\n"; *(const char * *)tb_grow(v_lines) = tb_v1773; }
    { const char * tb_v1774 = "    return r;\n"; *(const char * *)tb_grow(v_lines) = tb_v1774; }
    { const char * tb_v1775 = "}\n"; *(const char * *)tb_grow(v_lines) = tb_v1775; }
    { const char * tb_v1776 = "// ---------- background: работа в своём потоке ----------\n"; *(const char * *)tb_grow(v_lines) = tb_v1776; }
    { const char * tb_v1777 = "#ifndef TB_BARE\n"; *(const char * *)tb_grow(v_lines) = tb_v1777; }
    { const char * tb_v1778 = "typedef struct { pthread_t th; int done; void *res; } tb_task;\n"; *(const char * *)tb_grow(v_lines) = tb_v1778; }
    { const char * tb_v1779 = "static void tb_task_start(tb_task *t, void *(*run)(void *), void *arg) {\n"; *(const char * *)tb_grow(v_lines) = tb_v1779; }
    { const char * tb_v1780 = "    t->done = 0;\n"; *(const char * *)tb_grow(v_lines) = tb_v1780; }
    { const char * tb_v1781 = "    if (tb_thread_create(&t->th, run, arg) != 0) tb_crash(0, \"не получилось запустить background\");\n"; *(const char * *)tb_grow(v_lines) = tb_v1781; }
    { const char * tb_v1782 = "}\n"; *(const char * *)tb_grow(v_lines) = tb_v1782; }
    { const char * tb_v1783 = "// a.wait: дождаться потока (один раз) и отдать адрес ответа\n"; *(const char * *)tb_grow(v_lines) = tb_v1783; }
    { const char * tb_v1784 = "static void *tb_wait(tb_task *t) {\n"; *(const char * *)tb_grow(v_lines) = tb_v1784; }
    { const char * tb_v1785 = "    if (!t->done) { pthread_join(t->th, 0); t->done = 1; }\n"; *(const char * *)tb_grow(v_lines) = tb_v1785; }
    { const char * tb_v1786 = "    return t->res;\n"; *(const char * *)tb_grow(v_lines) = tb_v1786; }
    { const char * tb_v1787 = "}\n"; *(const char * *)tb_grow(v_lines) = tb_v1787; }
    { const char * tb_v1788 = "#endif\n"; *(const char * *)tb_grow(v_lines) = tb_v1788; }
    { const char * tb_v1789 = "static int tb_dhas(tb_dict *d, const void *k) { return tb_dfind(d, k) >= 0; }\n"; *(const char * *)tb_grow(v_lines) = tb_v1789; }
    { const char * tb_v1790 = "static void tb_dremove(tb_dict *d, const void *k) {\n"; *(const char * *)tb_grow(v_lines) = tb_v1790; }
    { const char * tb_v1791 = "    long long at = tb_dfind(d, k);\n"; *(const char * *)tb_grow(v_lines) = tb_v1791; }
    { const char * tb_v1792 = "    if (at < 0) return;\n"; *(const char * *)tb_grow(v_lines) = tb_v1792; }
    { const char * tb_v1793 = "    if (d->mode != 0) tb_dto_hash(d);\n"; *(const char * *)tb_grow(v_lines) = tb_v1793; }
    { const char * tb_v1794 = "    long long last = d->keys->len - 1;\n"; *(const char * *)tb_grow(v_lines) = tb_v1794; }
    { const char * tb_v1795 = "    // на место удалённого ставим последний: порядок меняется только у него\n"; *(const char * *)tb_grow(v_lines) = tb_v1795; }
    { const char * tb_v1796 = "    memcpy(d->keys->data + at * d->keys->size, d->keys->data + last * d->keys->size, d->keys->size);\n"; *(const char * *)tb_grow(v_lines) = tb_v1796; }
    { const char * tb_v1797 = "    memcpy(d->vals->data + at * d->vals->size, d->vals->data + last * d->vals->size, d->vals->size);\n"; *(const char * *)tb_grow(v_lines) = tb_v1797; }
    { const char * tb_v1798 = "    d->keys->len -= 1;\n"; *(const char * *)tb_grow(v_lines) = tb_v1798; }
    { const char * tb_v1799 = "    d->vals->len -= 1;\n"; *(const char * *)tb_grow(v_lines) = tb_v1799; }
    { const char * tb_v1800 = "    tb_dreindex(d, d->nslots);\n"; *(const char * *)tb_grow(v_lines) = tb_v1800; }
    { const char * tb_v1801 = "}\n"; *(const char * *)tb_grow(v_lines) = tb_v1801; }
    { const char * tb_v1802 = "static tb_dict *tb_dict_from(int text, long long vsize, long long n, const void *keys, const void *vals) {\n"; *(const char * *)tb_grow(v_lines) = tb_v1802; }
    { const char * tb_v1803 = "    tb_dict *d = tb_dict_new(text, vsize);\n"; *(const char * *)tb_grow(v_lines) = tb_v1803; }
    { const char * tb_v1804 = "    long long ksize = d->keys->size;\n"; *(const char * *)tb_grow(v_lines) = tb_v1804; }
    { const char * tb_v1805 = "    for (long long i = 0; i < n; i++) {\n"; *(const char * *)tb_grow(v_lines) = tb_v1805; }
    { const char * tb_v1806 = "        memcpy(tb_dput(d, (const char *)keys + i * ksize, 0), (const char *)vals + i * vsize, vsize);\n"; *(const char * *)tb_grow(v_lines) = tb_v1806; }
    { const char * tb_v1807 = "    }\n"; *(const char * *)tb_grow(v_lines) = tb_v1807; }
    { const char * tb_v1808 = "    return d;\n"; *(const char * *)tb_grow(v_lines) = tb_v1808; }
    { const char * tb_v1809 = "}\n"; *(const char * *)tb_grow(v_lines) = tb_v1809; }
    { const char * tb_v1810 = "\n"; *(const char * *)tb_grow(v_lines) = tb_v1810; }
    { const char * tb_v1811 = "// ---------- on all cores: цикл на всех ядрах ----------\n"; *(const char * *)tb_grow(v_lines) = tb_v1811; }
    { const char * tb_v1812 = "// Работа делится на куски; каждое ядро берёт следующий свободный кусок,\n"; *(const char * *)tb_grow(v_lines) = tb_v1812; }
    { const char * tb_v1813 = "// пока они не кончатся (так ядра не простаивают, если куски разные по тяжести).\n"; *(const char * *)tb_grow(v_lines) = tb_v1813; }
    { const char * tb_v1814 = "// shared: каждое ядро копит своё на «листке», потом один раз добавляет под замком.\n"; *(const char * *)tb_grow(v_lines) = tb_v1814; }
    { const char * tb_v1815 = "static pthread_mutex_t tb_par_lock = PTHREAD_MUTEX_INITIALIZER;\n"; *(const char * *)tb_grow(v_lines) = tb_v1815; }
    { const char * tb_v1816 = "static int tb_cores(void) {\n"; *(const char * *)tb_grow(v_lines) = tb_v1816; }
